def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = sum(1 for x in op if x == 'C')
    if opp_c == 0:
        return 'D'

    if n < 10:
        if op[-1] == 'D':
            return 'D'
        return 'C'

    opp_d = n - opp_c

    last5 = op[-5:]
    last10 = op[-10:]
    d5 = sum(1 for x in last5 if x == 'D')
    d10 = sum(1 for x in last10 if x == 'D')

    trailing_op_d = 0
    for x in reversed(op):
        if x == 'D':
            trailing_op_d += 1
        else:
            break

    my_last = my[-1]
    op_last = op[-1]

    start = n - 15
    if start < 1:
        start = 1

    recent_punish = 0
    recent_no_punish = 0
    for i in range(start, n):
        if my[i - 1] == 'D':
            if op[i] == 'D':
                recent_punish += 1
            else:
                recent_no_punish += 1

    exploitable = (
        recent_punish == 0 and
        recent_no_punish >= 1 and
        opp_c * 10 >= n * 7
    )

    if op_last == 'D':
        if trailing_op_d >= 5 or opp_d * 5 >= n * 4:
            return 'D'

        if trailing_op_d >= 3 and opp_c * 3 >= n * 2:
            return 'C'

        if trailing_op_d <= 1 and d5 <= 1 and opp_d * 5 <= n:
            return 'C'

        if (
            trailing_op_d >= 2 and
            opp_c * 5 >= n * 3 and
            opp_d * 20 <= n * 7
        ):
            return 'C'

        if my_last == 'D' and opp_c * 4 >= n:
            return 'C'

        if opp_c * 10 >= n * 8:
            if rng.random() < 0.55:
                return 'D'
        else:
            if rng.random() < 0.75:
                return 'D'

        return 'C'

    if exploitable:
        return 'D'

    if my_last == 'D':
        return 'C'

    if opp_d == 0:
        return 'D'

    if n >= 15 and d5 == 0 and opp_c * 10 >= n * 7:
        if rng.random() < 0.04:
            return 'D'

    return 'C'
